public static void Apply(MdiFrame frame, bool polish) {
Dictionary<string,ToolStripMenuItem> fields = Fields(frame);
frame.menuMain.Items.Clear();
foreach (Node node in Roots) {
ToolStripMenuItem root = Build(frame, fields, node, polish);
if (root == null) continue;
frame.menuMain.Items.Add(root);
root.DropDownOpening += delegate(object sender, EventArgs e) { frame.RefreshAgreedDynamicMenuNames(); };
}
frame.menuMain.MdiWindowListItem = frame.menuWindow;
}

static Dictionary<string,ToolStripMenuItem> Fields(MdiFrame frame) {
Dictionary<string,ToolStripMenuItem> result = new Dictionary<string,ToolStripMenuItem>();
foreach (FieldInfo field in typeof(MdiFrame).GetFields(BindingFlags.Public | BindingFlags.Instance)) {
ToolStripMenuItem item = field.GetValue(frame) as ToolStripMenuItem;
if (item != null) result[field.Name] = item;
}
return result;
}

static ToolStripMenuItem Build(MdiFrame frame, Dictionary<string,ToolStripMenuItem> fields, Node node, bool polish) {
ToolStripMenuItem item;
if (!fields.TryGetValue(node.Id, out item)) item = new ToolStripMenuItem();
if (item.Owner != null) item.Owner.Items.Remove(item);
item.DropDownItems.Clear();
item.Name = fields.ContainsKey(node.Id) ? item.Name : node.Id;
ApplyText(item, node.English, node.Polish, node.EnglishMnemonic, node.PolishMnemonic, polish);
foreach (Node child in node.Children) {
ToolStripMenuItem childItem = Build(frame, fields, child, polish);
if (childItem != null) item.DropDownItems.Add(childItem);
}
if (!fields.ContainsKey(node.Id) && item.DropDownItems.Count == 0) return null;
return item;
}

public static void ApplyText(ToolStripMenuItem item, string english, string polish, string englishMnemonic, string polishMnemonic, bool polishMode) {
string text = polishMode ? polish : english;
string mnemonic = polishMode ? polishMnemonic : englishMnemonic;
item.Text = AddMnemonic(text, mnemonic);
string key = item.ShortcutKeyDisplayString ?? "";
item.AccessibleName = text + (key.Length == 0 ? "" : "   " + key);
}

static string AddMnemonic(string text, string mnemonic) {
if (String.IsNullOrEmpty(mnemonic)) return text;
int index = text.IndexOf(mnemonic, StringComparison.OrdinalIgnoreCase);
return index < 0 ? text : text.Substring(0,index) + "&" + text.Substring(index);
}
